// Locally vendored copy of the Acme Widgets analytics tag (aw.js).
// Originally loaded from https://cdn.acme-widgets.test/aw.js, but kiosks
// have no network access, so this file is bundled and served locally
// instead of being fetched from the CDN at runtime.
(function () {
  window.AcmeWidgets = window.AcmeWidgets || {
    track: function (event) {
      // no-op offline stub; replace with real vendored widget code
      // if/when the upstream script contents are available.
      console.log("aw.js (local): track", event);
    },
  };
})();

// Build step for the kiosk page: copies src/index.html (and its local
// assets) to dist/. The analytics tag is served from a locally vendored
// copy (aw.js) instead of the CDN, since kiosks have no network access
// and dist/index.html must not contain any http:// or https:// references.
const fs = require("fs");

fs.mkdirSync("dist", { recursive: true });
fs.copyFileSync("src/index.html", "dist/index.html");
fs.copyFileSync("src/aw.js", "dist/aw.js");
console.log("built dist/index.html (+ dist/aw.js)");
